 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    # Locate the three-cell reference sprite as a straight contiguous run.
    runs = []
    for r in range(h):
        for c in range(w):
            for dr, dc in ((0, 1), (1, 0)):
                cells = [(r + i * dr, c + i * dc) for i in range(3)]
                if all(rr < h and cc < w and grid[rr][cc] != bg for rr, cc in cells):
                    runs.append(cells)
    if not runs:
        return [row[:] for row in grid]
    # The reference is distinguished by being the only contiguous run; if there
    # are several, prefer the one with the least common colors overall.
    def run_score(cells):
        vals = [grid[r][c] for r, c in cells]
        return (sum(Counter(v for row in grid for v in row)[v] for v in vals), cells[0][0], cells[0][1])
    ref = min(runs, key=run_score)
    r0, c0 = ref[1]
    pattern = [(r - r0, c - c0, grid[r][c]) for r, c in ref]
    excluded = set(ref)
    counts = Counter(grid[r][c] for r in range(h) for c in range(w)
                     if grid[r][c] != bg and (r, c) not in excluded)
    if not counts:
        return [row[:] for row in grid]
    target = counts.most_common(1)[0][0]
    out = [row[:] for row in grid]
    targets = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] == target and (r, c) not in excluded]
    for r, c in targets:
        for dr, dc, value in pattern:
            rr, cc = r + dr, c + dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = value
    return out
